   var original=mountain.GetComponentsInChildren<Transform>(true);var matrices=original.Select(t=>t.localToWorldMatrix).ToArray();var obstacles=new List<Bounds>();foreach(string name in new[]{"Central Upper Floor Building","Large Upper Castle Church","Large Courtyard Rook Tower","Old Fountain In Front Of Chapel","Upper Blacksmith And Boxwood Borders/Upper Courtyard Blacksmith"}){var t=mountain.transform.Find(name);if(t&&t.gameObject.activeInHierarchy)obstacles.Add(BoundsOf(t.gameObject));}
