   var root=new GameObject("Two Inner Mixed Grass Garden Plates");root.transform.SetParent(mountain.transform,false);Undo.RegisterCreatedObjectUndo(root,"Build two mixed garden plates");var area=floor.bounds;Vector3 center=area.center;center.y=area.max.y;var direction=Vector3.ProjectOnPlane(BoundsOf(fountain.gameObject).center-BoundsOf(elevator.gameObject).center,Vector3.up).normalized;var across=Vector3.Cross(direction,Vector3.up).normalized;float rx=area.extents.x*.8f-2.5f,rz=area.extents.z*.8f-2.5f,step=.65f,y=center.y+.10f;var selected=new HashSet<Vector2Int>();int[] counts={0,0};Physics.SyncTransforms();
