    foreach(var cell in selected){float x=area.min.x+cell.x*step,z=area.min.z+cell.y*step;var pos=new Vector3(x+step*.5f,y,z+step*.5f);if((Vector3.Dot(pos-center,across)>0?1:0)!=side)continue;var corners=Corners(x,z,step,y);int first=vertices.Count;foreach(var q in corners){vertices.Add(group.transform.InverseTransformPoint(q));colors.Add(new Color(Brown(q),0,0,1));}indices.AddRange(new[]{first,first+2,first+1,first,first+3,first+2});
