     if(cell.x%2==0&&cell.y%2==0&&Brown(pos)<.65f){Plant(grassPrefab,group.transform,pos,.30f,"Grass Clump "+(++blades).ToString("0000"),cell.x*17+cell.y*29);}
     if(cell.x%7==1&&cell.y%5==2){Plant(flowerPrefab,group.transform,pos,.42f,"Flowers "+(++flowers).ToString("000"),cell.x*37+cell.y*13);}
