  static float Brown(Vector3 p){float noise=.7f*Mathf.PerlinNoise((p.x+1847)/19f,(p.z+937)/19f)+.3f*Mathf.PerlinNoise((p.x+391)/6f,(p.z+2367)/6f);return Mathf.SmoothStep(0,1,Mathf.InverseLerp(.49f,.69f,noise))*.92f;}
  static Vector3[] Corners(float x,float z,float step,float y){return new[]{new Vector3(x,y,z),new Vector3(x+step,y,z),new Vector3(x+step,y,z+step),new Vector3(x,y,z+step)};}
  static void Plant(GameObject prefab,Transform parent,Vector3 target,float height,string name,int seed){var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab);go.transform.SetParent(parent,true);go.transform.rotation=Quaternion.Euler(0,seed%360,0);var b=BoundsOf(go);go.transform.localScale*=height/Mathf.Max(.001f,b.size.y);b=BoundsOf(go);go.transform.position+=new Vector3(target.x-b.center.x,target.y+.01f-b.min.y,target.z-b.center.z);go.name=name;foreach(var c in go.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);}
  static void Border(Transform parent,Vector3 a,Vector3 b,List<Vector3> v,List<int> ids){var right=Vector3.Cross((b-a).normalized,Vector3.up)*.065f;int first=v.Count;foreach(var p in new[]{a-right-Vector3.up*.08f,b-right-Vector3.up*.08f,b+right-Vector3.up*.08f,a+right-Vector3.up*.08f,a-right+Vector3.up*.02f,b-right+Vector3.up*.02f,b+right+Vector3.up*.02f,a+right+Vector3.up*.02f})v.Add(parent.InverseTransformPoint(p));int[] t={4,6,5,4,7,6,0,5,1,0,4,5,1,6,2,1,5,6,2,7,3,2,6,7,3,4,0,3,7,4};foreach(int i in t)ids.Add(first+i);}
  static Vector2 Flat(Vector3 p){return new Vector2(p.x,p.z);}
  static bool Intersects(Vector2[] a,Vector2[] b){foreach(var polygon in new[]{a,b})for(int i=0;i<polygon.Length;i++){var edge=polygon[(i+1)%polygon.Length]-polygon[i];if(edge.sqrMagnitude<.00001f)continue;var axis=new Vector2(-edge.y,edge.x).normalized;float amin=float.PositiveInfinity,amax=float.NegativeInfinity,bmin=amin,bmax=amax;foreach(var p in a){float v=Vector2.Dot(axis,p);amin=Mathf.Min(amin,v);amax=Mathf.Max(amax,v);}foreach(var p in b){float v=Vector2.Dot(axis,p);bmin=Mathf.Min(bmin,v);bmax=Mathf.Max(bmax,v);}if(amax<bmin||bmax<amin)return false;}return true;}
